package curated

import (
	"fmt"
	"regexp"
	"testing"
)

// Code generated by regengo
// Tests and benchmarks for pattern: [a-z]+

var dFACharClassRegexp = regexp.MustCompile("[a-z]+")

var dFACharClassTestInputs = []string{"abc", "abcdefghijklmnopqrstuvwxyz", "ABC123", "test string with words"}

func TestDFACharClassMatchString(t *testing.T) {
	for _, input := range dFACharClassTestInputs {
		expected := dFACharClassRegexp.MatchString(input)
		got := DFACharClass{}.MatchString(input)
		if got != expected {
			t.Errorf("MatchString(%q) = %v, want %v", input, got, expected)
		}
	}
}

func TestDFACharClassMatchBytes(t *testing.T) {
	for _, input := range dFACharClassTestInputs {
		inputBytes := []byte(input)
		expected := dFACharClassRegexp.Match(inputBytes)
		got := DFACharClass{}.MatchBytes(inputBytes)
		if got != expected {
			t.Errorf("MatchBytes(%q) = %v, want %v", input, got, expected)
		}
	}
}

func BenchmarkDFACharClass(b *testing.B) {
	inputs := dFACharClassTestInputs

	b.Run("Match", func(b *testing.B) {
		for i, input := range inputs {
			input := input
			b.Run(fmt.Sprintf("Input[%d]", i), func(b *testing.B) {
				b.Run("stdlib", func(b *testing.B) {
					b.ReportAllocs()
					for b.Loop() {
						_ = dFACharClassRegexp.MatchString(input)
					}
				})
				b.Run("regengo", func(b *testing.B) {
					b.ReportAllocs()
					for b.Loop() {
						_ = DFACharClass{}.MatchString(input)
					}
				})
			})
		}
	})

}
